import { booleanAttribute, ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, Output, output, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { AvatarComponent } from '../../../../shared/components/avatar/avatar.component';
import { NgSelectModule } from '@ng-select/ng-select';
import { myTeamUsers } from '../../../interfaces/teamshare.interface';

@Component({
  selector: 'teamshare',
  standalone: true,
  imports: [MatSelectModule, FormsModule, MatCheckboxModule, AvatarComponent, NgSelectModule],
  templateUrl: './teamshare.component.html',
  styleUrl: './teamshare.component.scss'
})
export class TeamshareComponent {
  constructor(private cdr: ChangeDetectorRef) { }


  @Input() title: string = 'Share with my team';
  /** Text in the user-picker dropdown when no users are selected. Defaults to
   *  the share-flow copy; RT marknav overrides to "Filter annotations by user"
   *  because in that context the picker filters the annotation list rather
   *  than granting share permissions. */
  @Input() placeholder: string = 'Select a role in case to share';
  @Input({ transform: booleanAttribute }) required: boolean = false;
  @Input({ transform: booleanAttribute }) showbadge: boolean = false;
  @Input({ transform: booleanAttribute }) disableEdit: boolean = false;

  @Input({ transform: booleanAttribute }) adminPDisabled: boolean = false;

  activeContacts: myTeamUsers[] = [];
  checkall: boolean = false;
  Editall: boolean = false;
  shareall: boolean = false;
  Commentall: boolean = false;
  Copyall: boolean = false;

  @Input() nCaseid: string;
  @Input() userList: myTeamUsers[];
  @Input() disablePermissions: boolean;
  @Input() isDocLink: boolean = false;
  @Output() userListChange = new EventEmitter<myTeamUsers[]>();


  // checkallbox(ev) {
  //   if (ev.checked) {
  //     this.demoUsers.forEach(x => {
  //       x.isChecked = true;
  //     });
  //     this.Editall = true;
  //     this.Commentall = true;
  //     this.shareall = true;
  //     this.Copyall = true;

  //   }
  //   else {
  //     this.demoUsers.forEach(x => {
  //       x.isChecked = false;
  //     });
  //   }
  // }

  ngOnInit(): void {
    if (!this.userList?.length) {
      this.userList = [];
    }
    this.syncActiveContacts();
    // Mirror the master "Select All" checkbox to the initial row state so
    // a fully pre-selected list (e.g. RT marknav's "no filter applied"
    // default) doesn't render with the master box unchecked while every
    // row underneath is checked. ngOnChanges skips firstChange, so we
    // have to set it here for the initial render.
    this.checkall = this.allSelected();
  }



  ngOnChanges(changes: SimpleChanges): void {

    if (changes['userList'] && !changes['userList'].firstChange && this.userList) {
      // normalize and avoid undefineds
      for (const u of this.userList) {
        u.isSelected = !!u.isSelected;
        u.bCanEdit = !!u.bCanEdit;
        u.bCanCopy = !!u.bCanCopy;
        u.bCanReshare = !!u.bCanReshare;
        u.bCanComment = !!u.bCanComment;
      }

      this.syncActiveContacts();
      this.checkall = this.allSelected();
      this.syncHeaderFromRows(); // keep bulk toggles aligned if list comes pre-filled
    }
  }


  // ---------- Computed helpers ----------
  private allSelected(): boolean {
    return (this.userList?.length ?? 0) > 0 && this.userList!.every(u => u.isSelected);
  }

  get selectAllIndeterminate(): boolean {
    const total = this.userList?.length ?? 0;
    const selected = this.userList?.filter(u => u.isSelected).length ?? 0;
    return selected > 0 && selected < total;
  }

  // ---------- Core sync helpers ----------
  syncActiveContacts(): void {
    this.activeContacts = (this.userList ?? []).filter(u => u.isSelected);
    this.cdr.detectChanges();
  }

  private applyBulkPermissionsToSelected(type: 'E' | 'C' | 'S' | 'CM'): void {
    for (const u of this.userList ?? []) {
      if (this.adminPDisabled && u.isAdmin) { continue; }
      if (u.isSelected) {
        if (type == 'E') u.bCanEdit = this.Editall
        else if (type == 'C') u.bCanCopy = this.Copyall
        else if (type == 'S') u.bCanReshare = this.shareall
        else if (type == 'CM') u.bCanComment = this.Commentall
      }
    }
  }

  private clearPermissions(u: myTeamUsers): void {
    u.bCanEdit = false;
    u.bCanCopy = false;
    u.bCanReshare = false;
    u.bCanComment = false;
  }

  syncHeaderFromRows(): void {

    const sel = (this.userList ?? []).filter(u => u.isSelected);

    if (sel.length === 0) {
      this.Editall = this.Copyall = this.shareall = this.Commentall = false;
      return;
    }
    this.Editall = sel.every(u => !!u.bCanEdit);
    this.Copyall = sel.every(u => !!u.bCanCopy);
    this.shareall = sel.every(u => !!u.bCanReshare);
    this.Commentall = sel.every(u => !!u.bCanComment);
  }

  // ---------- UI event handlers ----------
  checkallbox(ev: MatCheckboxChange): void {
    const checked = ev.checked;
    this.checkall = checked;

    for (const u of this.userList ?? []) {
      if (this.adminPDisabled && u.isAdmin) { continue; }
      u.isSelected = checked;
      if (checked) {
        // when selecting all, apply current header permission toggles
        // u.bCanEdit = this.Editall;
        // u.bCanCopy = this.Copyall;
        // u.bCanReshare = this.shareall;
        // u.bCanComment = this.Commentall;
        u.bCanEdit = true;
        u.bCanCopy = true;
        u.bCanReshare = true;
        u.bCanComment = true;
      } else {
        // when clearing all, also clear row permissions
        this.clearPermissions(u);
      }
    }

    this.userListChange.emit(this.userList);
    this.syncActiveContacts();
    // keep header pills meaningful if the user toggles Select All off
    // if (!checked) {
    //   this.Editall = this.Copyall = this.shareall = this.Commentall = false;
    // }
    if (checked) {
      this.Editall = this.Copyall = this.shareall = this.Commentall = true;
    } else {
      this.Editall = this.Copyall = this.shareall = this.Commentall = false;
    }
  }

  checkC(ev: MatCheckboxChange, x: myTeamUsers): void {
    x.isSelected = ev.checked;

    if (!ev.checked) {
      // unselecting a row wipes its permissions
      this.clearPermissions(x);
    } else {
      // selecting a row inherits current header toggles
      // x.bCanEdit = this.Editall;
      // x.bCanCopy = this.Copyall;
      // x.bCanReshare = this.shareall;
      // x.bCanComment = this.Commentall;
      x.bCanEdit = true;
      x.bCanCopy = true;
      x.bCanReshare = true;
      x.bCanComment = true;
    }

    this.checkall = this.allSelected();
    this.userListChange.emit(this.userList);
    this.syncActiveContacts();
    this.syncHeaderFromRows();
  }

  // Bulk header permissions – apply to currently selected rows

  onChangeAll(val: boolean, type: 'E' | 'C' | 'S' | 'CM'): void {

    if (type == 'E') {
      this.Editall = val;
    } else if (type == 'C') {
      this.Copyall = val;
    } else if (type == 'S') {
      this.shareall = val;
    } else if (type == 'CM') {
      this.Commentall = val;
    }

    this.applyBulkPermissionsToSelected(type);
  }
}
